.dice-container {
    width: 260px;
    background: linear-gradient(180deg, #161b22 0%, #0d1117 100%);
    border: 1px solid #30363d;
    border-radius: 20px;
    padding: 20px;
    text-align: center;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    font-family: 'Segoe UI', system-ui, sans-serif;
    color: #fff;
  }

  .dice-header { margin-bottom: 20px; display: flex; flex-direction: column; gap: 4px; }
  .dice-title { color: #8b949e; font-size: 11px; letter-spacing: 2px; font-weight: bold; text-transform: uppercase; }
  .dice-sub { color: #58a6ff; font-size: 15px; font-weight: 600; text-shadow: 0 0 10px rgba(88,166,255,0.3); }

  .dice-display-area {
    position: relative; width: 85px; height: 85px; margin: 0 auto 20px;
    background: #0d1117; border: 2px solid #58a6ff; border-radius: 18px;
    display: flex; justify-content: center; align-items: center;
    box-shadow: inset 0 0 20px rgba(88, 166, 255, 0.2);
  }

  .dice-number { font-size: 38px; font-weight: 900; color: #fff; text-shadow: 0 0 15px #58a6ff; z-index: 5; transition: 0.2s; }
  .dice-blur { position: absolute; font-size: 38px; font-weight: 900; color: rgba(88, 166, 255, 0.3); filter: blur(4px); display: none; }
  .dice-glow { position: absolute; width: 100%; height: 100%; background: radial-gradient(circle, rgba(88, 166, 255, 0.15) 0%, transparent 70%); animation: dice_pulse 2s infinite; }

  .dice-result-text { font-size: 13px; color: #8b949e; margin-bottom: 15px; height: 18px; font-style: italic; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  .roll-btn {
    width: 100%; padding: 12px; background: #238636; border: 1px solid rgba(255,255,255,0.1);
    border-radius: 12px; color: #fff; font-weight: bold; cursor: pointer; transition: all 0.2s;
  }
  .roll-btn:hover { background: #2ea043; transform: translateY(-2px); box-shadow: 0 4px 12px rgba(46,160,67,0.3); }
  .roll-btn:active { transform: translateY(0); }
  .roll-btn:disabled { background: #21262d; color: #484f58; cursor: not-allowed; transform: none; box-shadow: none; }

  @keyframes dice_pulse { 0%, 100% { opacity: 0.4; } 50% { opacity: 1; } }
  .rolling_anim { animation: dice_shake 0.1s infinite; }
  @keyframes dice_shake {
    0% { transform: translate(1px, 1px) rotate(0deg); }
    50% { transform: translate(-1px, -1px) rotate(1deg); }
    100% { transform: translate(1px, -1px) rotate(-1deg); }
  }

component.script:
(function() {
  const id = "$id$";
  const sides = parseInt("$sides$") || 20;

  const btn = document.getElementById('roll_btn_' + id);
  const valEl = document.getElementById('dice_value_' + id);
  const blurEl = document.getElementById('dice_blur_' + id);
  const areaEl = document.getElementById('dice_area_' + id);
  const noteEl = document.getElementById('result_note_' + id);
  const optData = document.getElementById('opt_raw_' + id);

  if(!btn) return;

  btn.onclick = function() {

    btn.disabled = true;
    valEl.style.opacity = "0.3";
    blurEl.style.display = "block";
    areaEl.classList.add('rolling_anim');
    noteEl.innerText = "正在裁决...";

    let ticks = 0;
    const maxTicks = 15;

    const timer = setInterval(() => {
      const temp = Math.floor(Math.random() * sides) + 1;
      valEl.innerText = temp;
      blurEl.innerText = temp;

      if(ticks++ > maxTicks) {
        clearInterval(timer);


        const finalPoint = Math.floor(Math.random() * sides) + 1;
        valEl.innerText = finalPoint;


        valEl.style.opacity = "1";
        blurEl.style.display = "none";
        areaEl.classList.remove('rolling_anim');


        let rawContent = optData.innerText;

        const rangeRegex = /(\d+)\s*-\s*(\d+)\s*:\s*([^|]+)/g;
        let match;
        let matchedDesc = "";

        while ((match = rangeRegex.exec(rawContent)) !== null) {
          const min = parseInt(match[1]);
          const max = parseInt(match[2]);
          if (finalPoint >= min && finalPoint <= max) {
            matchedDesc = match[3].trim();
            break;
          }
        }


        const output = "骰子结果：" + finalPoint + " " + matchedDesc;
        noteEl.innerText = "鉴定完毕";

        if (window.fillInput) {
          window.fillInput(output);
          window.tempAppendMsg('<Achievement detail="点击组件投掷一个骰子">今日手气</Achievement>')
        } else {
          console.log("Direct Output:", output);
        }


        setTimeout(() => { 
          btn.disabled = false; 
          noteEl.innerText = "等待投掷...";
        }, 1500);
      }
    }, 60);
  };
})();
